def validate_cart_items(items: list[str]) -> bool:
    '''Validate a list of shopping cart item identifiers.

    This version uses strip() which only removes ASCII whitespace.
    Unicode whitespace characters like NBSP (\u00A0), em space (\u2003),
    or zero-width space (\u200B) are NOT stripped and treated as valid content.
    '''
    if not isinstance(items, list):
        return False

    length = len(items)
    if length < 1 or length > 10:
        return False

    for item in items:
        if not isinstance(item, str):
            return False
        # Bug: strip() only removes ASCII whitespace, not unicode whitespace
        if item.strip() == '':
            return False

    return True

def validate_cart_items(items: list[str]) -> bool:
